test('percent coupons apply before fixed coupons regardless of the order given', () => {
  const lines = [{ unitMinor: 1000, quantity: 1 }];
  const fixedThenPercent = priceOrder({
    lines,
    coupons: [
      { type: 'fixed', value: 100 },
      { type: 'percent', value: 10 },
    ],
  });
  const percentThenFixed = priceOrder({
    lines,
    coupons: [
      { type: 'percent', value: 10 },
      { type: 'fixed', value: 100 },
    ],
  });
  // Percent (10% of 1000 = 100) always applies first, then the fixed 100: 1000 - 100 - 100 = 800.
  assert.equal(fixedThenPercent.totalMinor, 800);
  assert.equal(percentThenFixed.totalMinor, 800);
  assert.deepEqual(fixedThenPercent, percentThenFixed);
});

test('the total never goes below 0, even with coupons larger than the order', () => {
  const result = priceOrder({
    lines: [{ unitMinor: 500, quantity: 1 }],
    coupons: [
      { type: 'fixed', value: 2000 },
      { type: 'percent', value: 50 },
    ],
  });
  assert.equal(result.totalMinor, 0);
  assert.equal(result.discountMinor, 500);
});

test('stacked fixed coupons never push the running total negative', () => {
  const result = priceOrder({
    lines: [{ unitMinor: 300, quantity: 1 }],
    coupons: [
      { type: 'fixed', value: 200 },
      { type: 'fixed', value: 200 },
    ],
  });
  assert.equal(result.totalMinor, 0);
});

test('invalid coupons are rejected', () => {
  const lines = [{ unitMinor: 1000, quantity: 1 }];
  for (const coupon of [
    { type: 'percent', value: 0 },
    { type: 'percent', value: 101 },
    { type: 'percent', value: 1.5 },
    { type: 'fixed', value: 0 },
    { type: 'fixed', value: -5 },
    { type: 'other', value: 10 },
  ]) {
    assert.throws(() => priceOrder({ lines, coupons: [coupon] }), /invalid_coupon/);
  }
});

test('percent discount rounds half to even', () => {
  // 25 * 50% = 12.5 -> rounds to even (12), discount 12, total 13.
  const result = priceOrder({
    lines: [{ unitMinor: 25, quantity: 1 }],
    coupons: [{ type: 'percent', value: 50 }],
  });
  assert.equal(result.discountMinor, 12);
  assert.equal(result.totalMinor, 13);
});
